using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfiguration = CreateReportingConfiguration();
    }

    [AssemblyCleanup]
    public static async Task Cleanup()
    {
        if (s_reportingConfiguration is not null)
        {
            await s_reportingConfiguration.DisposeAsync();
        }
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var storageDir = Path.Combine(
            Path.GetDirectoryName(typeof(EvaluationTests).Assembly.Location)!,
            "eval-results");

        return DiskBasedReportingConfiguration.Create(
            storageRootDir: storageDir,
            evaluators:
            [
                new RelevanceEvaluator(),
                new CoherenceEvaluator(),
                new FluencyEvaluator(),
            ],
            chatConfiguration: GetChatConfiguration());
    }

    private static ChatConfiguration GetChatConfiguration()
    {
        // The evaluator model used to judge responses.
        // Configure via environment variable or replace with your endpoint.
        var endpoint = Environment.GetEnvironmentVariable("EVALUATION_MODEL_ENDPOINT")
            ?? "https://YOUR_ENDPOINT.openai.azure.com/";
        var deployment = Environment.GetEnvironmentVariable("EVALUATION_MODEL_DEPLOYMENT")
            ?? "gpt-4o";
        var key = Environment.GetEnvironmentVariable("EVALUATION_MODEL_KEY") ?? "";

        IChatClient evaluatorClient = new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new System.ClientModel.ApiKeyCredential(key))
            .GetChatClient(deployment)
            .AsIChatClient();

        return new ChatConfiguration(evaluatorClient);
    }

    [TestMethod]
    public async Task Chat_Response_IsRelevant()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_Response_IsRelevant));

        // Arrange: set up the chat messages
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        // Act: get a response from the chat client under test
        var chatClient = GetChatClientUnderTest();
        var response = await chatClient.GetResponseAsync(messages);

        // Evaluate the response
        messages.AddRange(response.Messages);
        await scenario.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task Chat_Response_IsCoherent()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_Response_IsCoherent));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain how photosynthesis works in two sentences.")
        };

        var chatClient = GetChatClientUnderTest();
        var response = await chatClient.GetResponseAsync(messages);

        messages.AddRange(response.Messages);
        await scenario.EvaluateAsync(messages);
    }

    private static IChatClient GetChatClientUnderTest()
    {
        // Configure the chat client under test.
        // In integration scenarios, this would come from the Aspire app host.
        var endpoint = Environment.GetEnvironmentVariable("CHAT_MODEL_ENDPOINT")
            ?? "https://YOUR_ENDPOINT.openai.azure.com/";
        var deployment = Environment.GetEnvironmentVariable("CHAT_MODEL_DEPLOYMENT")
            ?? "gpt-4o";
        var key = Environment.GetEnvironmentVariable("CHAT_MODEL_KEY") ?? "";

        return new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new System.ClientModel.ApiKeyCredential(key))
            .GetChatClient(deployment)
            .AsIChatClient();
    }
}

using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

/// <summary>
/// Integration evaluation tests that exercise the chat client through the Aspire app host.
/// These tests require the app host dependencies (Azure OpenAI) to be configured.
/// </summary>
[TestClass]
[TestCategory("Integration")]
public class IntegrationEvaluationTests
{
    private static DistributedApplication? s_app;
    private static ReportingConfiguration? s_reportingConfiguration;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        var appHost = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        s_app = await appHost.BuildAsync();
        await s_app.StartAsync();

        s_reportingConfiguration = CreateReportingConfiguration();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (s_reportingConfiguration is not null)
        {
            await s_reportingConfiguration.DisposeAsync();
        }

        if (s_app is not null)
        {
            await s_app.DisposeAsync();
        }
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var storageDir = Path.Combine(
            Path.GetDirectoryName(typeof(IntegrationEvaluationTests).Assembly.Location)!,
            "eval-results-integration");

        return DiskBasedReportingConfiguration.Create(
            storageRootDir: storageDir,
            evaluators:
            [
                new RelevanceEvaluator(),
                new CoherenceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ],
            chatConfiguration: GetEvaluatorChatConfiguration());
    }

    private static ChatConfiguration GetEvaluatorChatConfiguration()
    {
        var endpoint = Environment.GetEnvironmentVariable("EVALUATION_MODEL_ENDPOINT")
            ?? "https://YOUR_ENDPOINT.openai.azure.com/";
        var deployment = Environment.GetEnvironmentVariable("EVALUATION_MODEL_DEPLOYMENT")
            ?? "gpt-4o";
        var key = Environment.GetEnvironmentVariable("EVALUATION_MODEL_KEY") ?? "";

        IChatClient evaluatorClient = new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new System.ClientModel.ApiKeyCredential(key))
            .GetChatClient(deployment)
            .AsIChatClient();

        return new ChatConfiguration(evaluatorClient);
    }

    [TestMethod]
    public async Task AppHost_Chat_QualityEvaluation()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(AppHost_Chat_QualityEvaluation));

        // Resolve the chat client from the running app host
        var chatClient = s_app!.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        messages.AddRange(response.Messages);
        await scenario.EvaluateAsync(messages);
    }
}

